export class ENDODictionaryUtils {
  static findByCode(code: string): MedicalCodeEntry | undefined {
    return ENDO_ICD10_DATABASE.find(item => item.code.toLowerCase() === code.toLowerCase());
  }

  static searchByDescription(query: string): MedicalCodeEntry[] {
    const q = query.toLowerCase();
    return ENDO_ICD10_DATABASE.filter(item => item.description.toLowerCase().includes(q));
  }
}
